<script setup>
import {nextTick,onMounted,onUnmounted,ref,watch} from 'vue';
import axios from 'axios';
import {X,ArrowUp,ArrowDown} from '@lucide/vue';
const props=defineProps({apiBase:String,sessionToken:String,preferences:Object});const emit=defineEmits(['close','saved']);
const dialog=ref(null),previousFocus=document.activeElement;
function trapTab(event){const nodes=[...dialog.value.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled)')];if(event.shiftKey && document.activeElement===nodes[0]){event.preventDefault();nodes.at(-1)?.focus();}else if(!event.shiftKey && document.activeElement===nodes.at(-1)){event.preventDefault();nodes[0]?.focus();}}
onMounted(async()=>{await nextTick();dialog.value?.querySelector('select')?.focus();});onUnmounted(()=>{if(previousFocus?.isConnected)previousFocus.focus();else document.querySelector('[aria-label="My Account"]')?.focus();});
const draft=ref({}),busy=ref(false),error=ref('');
const destinations=[['calendar','Today'],['home','Messages'],['tasks','Tasks'],['mywork','My Work'],['noteaid','Note Workspace'],['contacts','Contacts'],['presence','Presence']];
watch(()=>props.preferences,value=>{draft.value={...value,pinnedNavigation:[...(value?.pinnedNavigation || ['calendar','home','tasks'])]};},{immediate:true});
function toggle(id){const ids=draft.value.pinnedNavigation;draft.value.pinnedNavigation=ids.includes(id)?ids.filter(item=>item!==id):[...ids,id].slice(0,4);}
function move(index,step){const ids=[...draft.value.pinnedNavigation],other=index+step;if(other<0 || other>=ids.length)return;[ids[index],ids[other]]=[ids[other],ids[index]];draft.value.pinnedNavigation=ids;}
async function save(){busy.value=true;error.value='';try{const {data}=await axios.patch(`${props.apiBase}/messages/preferences`,draft.value,{headers:{'X-Quick-View-Session':props.sessionToken},withCredentials:true});emit('saved',data.preferences);emit('close');}catch(e){error.value=e.response?.data?.error?.message || 'Could not save your settings.';}finally{busy.value=false;}}
</script>
<template>
  <Teleport to="body"><div class="mobile-settings-overlay" @keydown.esc="emit('close')"><section ref="dialog" @keydown.tab="trapTab" role="dialog" aria-modal="true" aria-labelledby="mobile-settings-title"><header><h2 id="mobile-settings-title">Mobile preferences</h2><button aria-label="Close mobile preferences" @click="emit('close')"><X :size="22"/></button></header><form @submit.prevent="save"><p>These choices follow your account on your mobile devices.</p>
    <label for="mobile-swipeLeft">Swipe left</label><select id="mobile-swipeLeft" v-model="draft.swipeLeft"><option value="archive">Archive / restore</option><option value="read">Mark read</option><option value="unread">Mark unread</option><option value="none">No action</option></select>
    <label for="mobile-swipeRight">Swipe right</label><select id="mobile-swipeRight" v-model="draft.swipeRight"><option value="read">Mark read</option><option value="archive">Archive / restore</option><option value="unread">Mark unread</option><option value="none">No action</option></select>
    <label for="mobile-navigationMode">Bottom navigation</label><select id="mobile-navigationMode" v-model="draft.navigationMode"><option value="automatic">Most frequently used</option><option value="pinned">My selected shortcuts</option></select>
    <p v-if="draft.navigationMode==='automatic'">Your most-used tools move into the available slots. More always contains every tool.</p>
    <template v-else><p>Choose up to four tools. Narrow screens show fewer shortcuts; the rest stay in More.</p><fieldset><legend>Shortcuts</legend><label v-for="[id,label] in destinations" :key="id" class="choice"><input type="checkbox" :checked="draft.pinnedNavigation.includes(id)" :disabled="!draft.pinnedNavigation.includes(id) && draft.pinnedNavigation.length>=4" @change="toggle(id)"/>{{ label }}</label></fieldset><ol><li v-for="(id,index) in draft.pinnedNavigation" :key="id"><span>{{ destinations.find(d=>d[0]===id)?.[1] }}</span><button type="button" :aria-label="`Move ${id} up`" :disabled="index===0" @click="move(index,-1)"><ArrowUp :size="16"/></button><button type="button" :aria-label="`Move ${id} down`" :disabled="index===draft.pinnedNavigation.length-1" @click="move(index,1)"><ArrowDown :size="16"/></button></li></ol></template>
    <p v-if="error" role="alert">{{ error }}</p><button class="save" :disabled="busy || !draft.pinnedNavigation.length">{{ busy?'Saving…':'Save preferences' }}</button>
  </form></section></div></Teleport>
</template>
<style scoped>
.mobile-settings-overlay{position:fixed;inset:0;z-index:180;display:grid;place-items:center;padding:16px;background:#17355488;font:14px/1.5 Inter,-apple-system,sans-serif;color:#1e385c}.mobile-settings-overlay section{width:100%;max-width:440px;box-sizing:border-box;background:#fff;border-radius:18px;padding:22px;max-height:90dvh;overflow:auto}header{display:flex;justify-content:space-between;align-items:center}h2{font-size:19px;margin:0}button{font:inherit;cursor:pointer;border:0;background:transparent;color:inherit;padding:8px}p{font-size:12px;color:#6a7d97}label{display:block;font-size:12px;font-weight:600;margin:17px 0 0}select{width:100%;box-sizing:border-box;padding:12px;margin-top:7px;border:1px solid #d4dfef;background:#fafcff;border-radius:10px;color:inherit;font:inherit}fieldset{border:1px solid #e0e8f5;border-radius:10px}.choice{display:flex;gap:10px;align-items:center;margin:9px 0;font-weight:400}.choice input{width:18px;height:18px}ol{padding:0;list-style:none}li{display:flex;align-items:center;border-bottom:1px solid #edf1f6;padding:6px;font-size:12px}li span{flex:1}.save{width:100%;border-radius:10px;background:#245be0;color:white;min-height:44px;margin-top:10px}button:disabled{opacity:.45;cursor:default}:focus-visible{outline:3px solid #7fa9f4;outline-offset:2px}
</style>
